def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1
            if opp.get('budget', 0) >= DAILY_SALARY * 2:
                rich_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return max(0, min(budget, 18.0))

    players = len(alive) + 1
    capacity = supply / float(WATER_REQ)
    scarcity = players - capacity

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / float(len(prev_bids))) if prev_bids else 0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2

    if scarcity > 1.5:
        danger += 2
    elif scarcity > 0.5:
        danger += 1

    if day >= 8:
        danger += 1

    if danger >= 6:
        bid = max(62.0, highest_prev + 3.0, avg_prev + 6.0)
    elif danger >= 4:
        bid = max(48.0, highest_prev + 2.0, avg_prev + 4.0)
    elif danger >= 2:
        bid = max(34.0, highest_prev + 1.0, avg_prev + 2.0)
    else:
        if capacity >= players:
            bid = 16.0
        elif capacity >= players - 0.5:
            bid = 22.0
        else:
            bid = 28.0

    if urgent_opponents >= max(1, len(alive) // 2):
        bid += 4.0
    if rich_opponents >= max(1, len(alive) // 2):
        bid += 3.0

    if highest_prev >= 60:
        if danger <= 2:
            bid = min(bid, 26.0)
        else:
            bid = max(bid, highest_prev + 1.5)

    reserve_target = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    affordable = budget - reserve_target
    if affordable < 0:
        affordable = budget * 0.5

    bid = min(bid, budget, max(0.0, affordable))

    if danger >= 5:
        bid = min(budget, max(bid, 58.0))
    elif hp <= 2 or no_water >= 2:
        bid = min(budget, max(bid, 64.0))

    if budget <= 20:
        bid = min(bid, budget)
    elif budget <= 40 and danger <= 2:
        bid = min(bid, 24.0)

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    yesterday_bids = []
    yesterday_hp_after = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass
            try:
                if prev.get('hp_after') is not None:
                    yesterday_hp_after.append(float(prev['hp_after']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    any_prev_urgent = False
    if yesterday_hp_after:
        # If any opponent's HP dropped dangerously after yesterday, treat as urgent.
        for h in yesterday_hp_after:
            if h <= 2.0:
                any_prev_urgent = True
                break

    # Estimate how many water units might be available; use to calibrate aggressiveness.
    # Ensure indices are integers where applicable (none used here), but keep safe math.
    approx_units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0
    if approx_units < 1:
        approx_units = 1

    # Budget safety: never bid more than what we can afford.
    def clamp_bid(x):
        x = float(x)
        if x < 0.0:
            x = 0.0
        if x > my_budget:
            x = my_budget
        return x

    # Core strategy
    # If opponents bid very high yesterday, they likely needed water badly today.
    urgent_threshold = DAILY_SALARY * 0.85

    if highest_prev_bid >= urgent_threshold or any_prev_urgent:
        # If we're also at risk, outbid more.
        if my_hp <= 2 or my_no_water_days >= 2:
            # Aggressive: aim to beat urgent bids.
            target = highest_prev_bid + 1.0
            # Cap by budget and a reasonable upper bound.
            return clamp_bid(min(target, DAILY_SALARY * 0.98, my_budget))
        else:
            # Moderate aggression: slightly above their likely clearing price.
            target = max(highest_prev_bid * 0.95, DAILY_SALARY * 0.65)
            return clamp_bid(min(target, DAILY_SALARY * 0.9, my_budget))

    # If yesterday bids were low, we can bid just enough to secure water.
    # Use supply to decide: higher supply -> lower bid.
    # Normalize supply within [MIN_SUPPLY, MAX_SUPPLY]
    if supply <= MIN_SUPPLY:
        supply_factor = 1.0
    elif supply >= MAX_SUPPLY:
        supply_factor = 0.6
    else:
        supply_factor = 1.0 - 0.4 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    # If our HP is low, increase bid.
    hp_factor = 1.0
    if my_hp <= 2:
        hp_factor = 1.25
    elif my_hp <= 3:
        hp_factor = 1.12
    elif my_no_water_days >= 2:
        hp_factor = 1.15

    base_bid = DAILY_SALARY * 0.45
    bid = base_bid * supply_factor * hp_factor

    # Ensure we don't bid too low if opponents likely still contest.
    if highest_prev_bid > 0.0:
        bid = max(bid, highest_prev_bid * 0.7)

    # If we can afford it and supply is tight, add a small premium.
    if approx_units <= 1:
        bid *= 1.15

    return clamp_bid(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opps = [o for o in opponents_status.values() if o['alive']]
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)
    # Get yesterday's bids
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    hp = my_status['hp']
    budget = my_status['budget']
    # Base bid
    base_bid = DAILY_SALARY * 0.5
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # Slightly outbid yesterday's highest
        base_bid = max(base_bid, max_prev + 1.5)
    # Adjust for urgency
    if hp <= 2:
        bid = min(budget, DAILY_SALARY * 0.95)
    elif hp <= 4:
        bid = min(budget, base_bid * 1.2)
    else:
        bid = min(budget, base_bid)
    # Ensure non-negative and cap at budget
    return max(0.0, min(budget, bid))
